        "sarlavha": "Internet: so'rov va javob",
        "izoh": "Brauzer so'rov yuboradi, server javob qaytaradi.",
        "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"50\" y=\"120\" width=\"180\" height=\"120\" rx=\"12\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"140\" y=\"160\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\">BRAUZER</text><text x=\"140\" y=\"185\" fill=\"#6d6f9c\" font-size=\"12\" font-weight=\"400\" text-anchor=\"middle\">(client)</text><text x=\"140\" y=\"215\" fill=\"#9a9cc4\" font-size=\"12\" font-weight=\"400\" text-anchor=\"middle\">siz</text><rect x=\"410\" y=\"120\" width=\"180\" height=\"120\" rx=\"12\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"500\" y=\"160\" fill=\"#7c5cff\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\">SERVER</text><text x=\"500\" y=\"185\" fill=\"#6d6f9c\" font-size=\"12\" font-weight=\"400\" text-anchor=\"middle\">(internetda)</text><line x1=\"232\" y1=\"150\" x2=\"408\" y2=\"150\" stroke=\"#38e1c8\" stroke-width=\"2.5\" marker-end=\"url(#vzar)\"/><text x=\"320\" y=\"140\" fill=\"#38e1c8\" font-size=\"13\" font-weight=\"600\" text-anchor=\"middle\">GET so'rov</text><line x1=\"408\" y1=\"210\" x2=\"232\" y2=\"210\" stroke=\"#7c5cff\" stroke-width=\"2.5\" marker-end=\"url(#vzar)\"/><text x=\"320\" y=\"232\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"600\" text-anchor=\"middle\">HTML javob</text></svg>"
