      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"120\" y=\"80\" width=\"400\" height=\"200\" rx=\"10\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><line x1=\"120\" y1=\"106\" x2=\"520\" y2=\"106\" stroke=\"#2a2c4e\" stroke-width=\"1\"/><text x=\"134\" y=\"98\" fill=\"#6d6f9c\" font-size=\"11\" font-weight=\"400\" text-anchor=\"start\">terminal</text><text x=\"140\" y=\"130\" fill=\"#38e1c8\" font-size=\"15\" font-weight=\"400\" text-anchor=\"start\">$ node server.js</text><text x=\"140\" y=\"170\" fill=\"#c6ff4f\" font-size=\"15\" font-weight=\"400\" text-anchor=\"start\">Salom serverdan!</text><text x=\"140\" y=\"215\" fill=\"#c6ff4f\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">✓ backend ishlaydi</text></svg>"
