      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"120\" y=\"75\" width=\"400\" height=\"120\" rx=\"10\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><line x1=\"120\" y1=\"101\" x2=\"520\" y2=\"101\" stroke=\"#2a2c4e\" stroke-width=\"1\"/><text x=\"134\" y=\"93\" fill=\"#6d6f9c\" font-size=\"11\" font-weight=\"400\" text-anchor=\"start\">terminal</text><text x=\"140\" y=\"120\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">$ node server.js</text><text x=\"140\" y=\"155\" fill=\"#c6ff4f\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">Server 3000-portda ✓</text><rect x=\"180\" y=\"210\" width=\"280\" height=\"90\" rx=\"12\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><circle cx=\"196\" cy=\"225\" r=\"4\" fill=\"#ff5f57\"/><circle cx=\"210\" cy=\"225\" r=\"4\" fill=\"#febc2e\"/><circle cx=\"224\" cy=\"225\" r=\"4\" fill=\"#28c840\"/><rect x=\"238\" y=\"217\" width=\"210\" height=\"16\" rx=\"8\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"246\" y=\"229\" fill=\"#6d6f9c\" font-size=\"10\" font-weight=\"400\" text-anchor=\"start\">localhost:3000</text><line x1=\"180\" y1=\"240\" x2=\"460\" y2=\"240\" stroke=\"#2a2c4e\" stroke-width=\"1\"/><text x=\"320\" y=\"270\" fill=\"#ecebff\" font-size=\"15\" font-weight=\"400\" text-anchor=\"middle\">Salom, serverim!</text></svg>"
