      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"140\" y=\"90\" width=\"360\" height=\"40\" rx=\"8\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"170\" y=\"115\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">id</text><text x=\"260\" y=\"115\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">ism</text><text x=\"400\" y=\"115\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">email</text><rect x=\"140\" y=\"135\" width=\"360\" height=\"44\" rx=\"0\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"170\" y=\"163\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">1</text><text x=\"260\" y=\"163\" fill=\"#ecebff\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">Ali</text><text x=\"400\" y=\"163\" fill=\"#9a9cc4\" font-size=\"13\" font-weight=\"400\" text-anchor=\"start\">ali@mail.uz</text><rect x=\"140\" y=\"183\" width=\"360\" height=\"44\" rx=\"0\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"170\" y=\"211\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">2</text><text x=\"260\" y=\"211\" fill=\"#ecebff\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">Vali</text><text x=\"400\" y=\"211\" fill=\"#9a9cc4\" font-size=\"13\" font-weight=\"400\" text-anchor=\"start\">vali@mail.uz</text></svg>"
