      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"90\" y=\"150\" width=\"130\" height=\"50\" rx=\"10\" fill=\"none\" stroke=\"#c6ff4f\" stroke-width=\"1.5\"/><text x=\"155\" y=\"180\" fill=\"#c6ff4f\" font-size=\"14\" font-weight=\"600\" text-anchor=\"middle\">Create ✓</text><line x1=\"222\" y1=\"175\" x2=\"282\" y2=\"175\" stroke=\"#6d6f9c\" stroke-width=\"2\" marker-end=\"url(#vzar)\"/><ellipse cx=\"340\" cy=\"150\" rx=\"55\" ry=\"14\" fill=\"#1b1c36\" stroke=\"#7c5cff\"/><path d=\"M285,150 L285,220 A55,14 0 0,0 395,220 L395,150\" fill=\"#1b1c36\" stroke=\"#7c5cff\"/><text x=\"340\" y=\"192\" fill=\"#7c5cff\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">DB</text><line x1=\"398\" y1=\"175\" x2=\"458\" y2=\"175\" stroke=\"#6d6f9c\" stroke-width=\"2\" marker-end=\"url(#vzar)\"/><rect x=\"460\" y=\"150\" width=\"130\" height=\"50\" rx=\"10\" fill=\"none\" stroke=\"#38e1c8\" stroke-width=\"1.5\"/><text x=\"525\" y=\"180\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"600\" text-anchor=\"middle\">Read ✓</text></svg>"
