        "s": "Hujjatlashtirish",
        "p": "Loyiha tayyor — endi uni professional hujjatlaysiz. README — loyihaning 'pasporti': u nima qiladi, qanday imkoniyatlari bor, qanday ishga tushiriladi. Toza Git tarixi — qilingan ishning tartibli yozuvi. Skrinshotlar, jonli demo havolasi."
